import{_ as a,o as i,c as e,a2 as n}from"./chunks/framework.DCVnL8g5.js";const k=JSON.parse('{"title":"SCP, SFTP y tunnels","description":"","frontmatter":{},"headers":[],"relativePath":"devops/ssh/04-scp-sftp-y-tunnels.md","filePath":"devops/ssh/04-scp-sftp-y-tunnels.md","lastUpdated":1789040978000,"isDraft":false}'),t={name:"devops/ssh/04-scp-sftp-y-tunnels.md"};function l(o,s,p,h,d,r){return i(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="scp-sftp-y-tunnels" tabindex="-1">SCP, SFTP y tunnels <a class="header-anchor" href="#scp-sftp-y-tunnels" aria-label="Permalink to &quot;SCP, SFTP y tunnels&quot;">​</a></h1><p>SSH no solo abre shell: copia archivos y reenvia puertos TCP. Eso permite editar remotos, sincronizar artefactos y alcanzar servicios privados (Postgres, Redis, paneles admin) como si estuvieran en localhost.</p><h2 id="scp" tabindex="-1">SCP <a class="header-anchor" href="#scp" aria-label="Permalink to &quot;SCP&quot;">​</a></h2><p>Copia puntual archivo a archivo:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Local -&gt; remoto</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./app.tar.gz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy@servidor:/var/www/</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Remoto -&gt; local</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy@servidor:/var/log/nginx/error.log</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./error.log</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Directorio recursivo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./dist/</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy@servidor:/var/www/app/</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Con alias de config y puerto ya definidos</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./backup.sql</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prod-api:/tmp/</span></span></code></pre></div><p><code>scp</code> usa el mismo <code>~/.ssh/config</code> que <code>ssh</code>.</p><p>Limitacion: no reanuda bien transferencias grandes interrumpidas. Para eso, <code>rsync</code> sobre SSH:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rsync</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -avz</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --progress</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./dist/</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy@servidor:/var/www/app/</span></span></code></pre></div><h2 id="sftp" tabindex="-1">SFTP <a class="header-anchor" href="#sftp" aria-label="Permalink to &quot;SFTP&quot;">​</a></h2><p>Sesion interactiva estilo FTP cifrado:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sftp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy@servidor</span></span></code></pre></div><p>Comandos habituales dentro de sftp:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ls</span></span>
<span class="line"><span>lcd ./local-dir</span></span>
<span class="line"><span>cd /var/www</span></span>
<span class="line"><span>put archivo.txt</span></span>
<span class="line"><span>get remoto.log</span></span>
<span class="line"><span>mkdir uploads</span></span>
<span class="line"><span>bye</span></span></code></pre></div><p>En scripts, preferible <code>scp</code>/<code>rsync</code> o el cliente SFTP no interactivo.</p><h2 id="tunnel-local-l" tabindex="-1">Tunnel local (<code>-L</code>) <a class="header-anchor" href="#tunnel-local-l" aria-label="Permalink to &quot;Tunnel local (\`-L\`)&quot;">​</a></h2><p>Expone un puerto remoto en tu maquina:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -N</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 5432:127.0.0.1:5432</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy@bastion</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Flag</th><th>Significado</th></tr></thead><tbody><tr><td><code>-L local:destino:puerto</code></td><td>Escucha local y reenvia al destino visto desde el remoto</td></tr><tr><td><code>-N</code></td><td>No abras shell; solo tunnel</td></tr></tbody></table><p>Ahora tu cliente Postgres apunta a <code>localhost:5432</code> y el trafico viaja cifrado hasta el bastion, que habla con Postgres en su <code>127.0.0.1</code>.</p><p>Via config:</p><div class="language-ssh-config vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ssh-config</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Host</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> db-tunnel</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  HostName</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> bastion.ejemplo.com</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  User</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> deploy</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  LocalForward</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5432</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 127.0.0.1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5432</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -N</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db-tunnel</span></span></code></pre></div><h2 id="tunnel-remoto-r" tabindex="-1">Tunnel remoto (<code>-R</code>) <a class="header-anchor" href="#tunnel-remoto-r" aria-label="Permalink to &quot;Tunnel remoto (\`-R\`)&quot;">​</a></h2><p>El servidor escucha y reenvia hacia tu laptop (menos frecuente; util para demos o webhooks temporales):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -N</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 8080:127.0.0.1:3000</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> usuario@servidor</span></span></code></pre></div><p>Quien conecte a <code>servidor:8080</code> llega a tu app local en <code>:3000</code> (si <code>GatewayPorts</code> lo permite en el servidor).</p><h2 id="tunnel-dinamico-d-socks" tabindex="-1">Tunnel dinamico (<code>-D</code>) SOCKS <a class="header-anchor" href="#tunnel-dinamico-d-socks" aria-label="Permalink to &quot;Tunnel dinamico (\`-D\`) SOCKS&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -N</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -D</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1080</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy@bastion</span></span></code></pre></div><p>Configura el navegador o <code>ALL_PROXY=socks5://127.0.0.1:1080</code> para salir a internet <strong>desde</strong> la red del bastion.</p><h2 id="casos-practicos" tabindex="-1">Casos practicos <a class="header-anchor" href="#casos-practicos" aria-label="Permalink to &quot;Casos practicos&quot;">​</a></h2><ol><li><strong>Adminer / Grafana internos</strong> sin abrir el puerto al mundo:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -N</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 3000:10.0.1.50:3000</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bastion</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Abrir http://127.0.0.1:3000</span></span></code></pre></div><ol start="2"><li><strong>Copiar logs de incidente</strong>:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prod-api:/var/log/app/error.log</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./incident-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">date</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +%F</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.log</span></span></code></pre></div><ol start="3"><li><strong>Despliegue simple de estaticos</strong>:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rsync</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -avz</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --delete</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./dist/</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy@prod-api:/var/www/app/</span></span></code></pre></div><h2 id="errores-habituales" tabindex="-1">Errores habituales <a class="header-anchor" href="#errores-habituales" aria-label="Permalink to &quot;Errores habituales&quot;">​</a></h2><ul><li>Confundir <code>-L 5432:localhost:5432</code> pensando que <code>localhost</code> es tu PC: en <code>-L</code>, el host del medio se resuelve <strong>desde el servidor SSH</strong>.</li><li>Dejar tunnels abiertos con servicios sensibles en <code>0.0.0.0</code> local.</li><li>Usar <code>scp</code> recursivo sobre node_modules o .git enormes.</li><li>Olvidar <code>-N</code> y cerrar el tunnel al hacer <code>exit</code> del shell (a veces deseable; a veces no).</li></ul><h2 id="buenas-practicas" tabindex="-1">Buenas practicas <a class="header-anchor" href="#buenas-practicas" aria-label="Permalink to &quot;Buenas practicas&quot;">​</a></h2><ul><li>Tunnels con <code>-N</code> en una terminal dedicada o servicio de usuario.</li><li>No publiques <code>-R</code> en produccion sin autenticacion adicional.</li><li>Prefiere VPN o mesh (WireGuard, Tailscale) si el acceso interno es diario y amplio.</li><li>Audita quien tiene capacidad de abrir tunnels a datos productivos.</li></ul><h2 id="ejercicio" tabindex="-1">Ejercicio <a class="header-anchor" href="#ejercicio" aria-label="Permalink to &quot;Ejercicio&quot;">​</a></h2><ol><li>Monta un tunnel local a un servicio (Postgres, Redis o un HTTP interno).</li><li>Conecta con el cliente contra <code>127.0.0.1</code>.</li><li>Copia un archivo con <code>scp</code> y sincroniza un directorio con <code>rsync -avz</code>.</li></ol><h2 id="siguiente-paso" tabindex="-1">Siguiente paso <a class="header-anchor" href="#siguiente-paso" aria-label="Permalink to &quot;Siguiente paso&quot;">​</a></h2><p>Continua con <a href="./05-hardening-del-servidor">Hardening del servidor</a>.</p>`,44)])])}const g=a(t,[["render",l]]);export{k as __pageData,g as default};
